import assert from 'node:assert/strict';
import test from 'node:test';
import {mkdirSync,writeFileSync,readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {gzipSync} from 'node:zlib';
import {createConcreteSyntaxMeta,serializeConcreteSyntaxMeta,parseConcreteSyntaxMeta,reconstructConcreteSyntax,applyConcreteSyntaxSubstitutions} from '../concrete-syntax-meta.mjs';
import {translateSource,translateSourceConcreteSyntaxMeta} from '../translate.mjs';
import {translateProject,resolveModuleGraph} from '../project.mjs';
import {parseProgram,serializeProgram} from '../semantic-meta.mjs';
import {PRODUCTION_PROFILE} from '../cfg-profile.mjs';
import {verifyTypedTargets} from './typed-targets.mjs';
const hash=value=>createHash('sha256').update(value).digest('hex');
const retain=(name,value)=>{const root=process.env.ROUTER_FORWARD_CST_VECTOR_DIR;if(!root)return;mkdirSync(root,{recursive:true});writeFileSync(root+'/'+name+'.json.gz',gzipSync(JSON.stringify(value,(_,entry)=>typeof entry==='bigint'?{$bigint:String(entry)}:entry instanceof Map?{$map:[...entry]}:entry)+'\n'));};
// Complete pre-273 consumer, including every original private semantic call.
const beforeSource=Buffer.from('','base64').toString('utf8');
assert.equal(hash(beforeSource),'efbf2b9dfee4279190ec069e92bb2bef7fcd0fff2e699935f0e71bf456da4534');
const relocations=[];const relocatedBefore=beforeSource.replace(/(\bfrom\s*['"])(\.[^'"]+)(['"])/gu,(_,a,b,c)=>{const to=new URL(b,new URL('../translate.mjs',import.meta.url)).href;relocations.push({from:b,to});return a+to+c;});
const reverseBefore=relocatedBefore.replace(/(\bfrom\s*['"])([^'"]+)(['"])/gu,(_,a,b,c)=>a+(relocations.find(row=>row.to===b)?.from??b)+c);assert.equal(reverseBefore,beforeSource);
const prior=await import('data:text/javascript;base64,'+Buffer.from(relocatedBefore).toString('base64'));
const serialize=source=>serializeConcreteSyntaxMeta(createConcreteSyntaxMeta(source,{language:'Rust'}));
function checkCst(document,source){
 assert.equal(document.schema,'meta-language-concrete-syntax-v1');assert.equal(document.representationLevel,'concrete-syntax');assert.equal(document.language,'Rust');assert.equal(document.source,source);
 assert.ok(['lexical','opaque','error'].includes(document.status));assert.ok(Object.keys(document.authority).length);for(const flag of Object.values(document.authority))assert.equal(flag,false);
 const text=serializeConcreteSyntaxMeta(document),parsed=parseConcreteSyntaxMeta(text);assert.deepEqual(parsed,document);assert.equal(serializeConcreteSyntaxMeta(parsed),text);assert.equal(reconstructConcreteSyntax(parsed),source);assert.deepEqual(Buffer.from(reconstructConcreteSyntax(parsed)),Buffer.from(source));
 return {text,sourceCodeUnits:source.length,sourceBytes:Buffer.byteLength(source),sourceSha256:hash(source)};
}
const plain=result=>{const {concreteSyntaxMeta,...ir}=result.ir;assert.ok(concreteSyntaxMeta);return {...result,ir};};
const outcome=call=>{try{return {value:call()};}catch(error){return {error:{name:error.name,message:error.message}};}};

test('complete comments raw strings nested comments BOM CRLF and Unicode survive the actual forward source boundary',{timeout:60000},()=>{
 const sources=['\uFEFF// café 🦀\r\n/* outer /* nested */ tail */\r\npub fn choose(flag:bool)->u8{if flag{7}else{9}}\r\n','const TEXT:&str=r###"quotes " # braces { } and 🦀"###;\n// final comment without newline','/// doc e\u0301\n/* nested /* levels */ end */ pub fn value()->u8{3}','pub fn empty()->u8{0}\r\n'];
 for(const [index,source]of sources.entries()){const serialized=serialize(source),direct=translateSource(source),fromMeta=translateSourceConcreteSyntaxMeta(serialized);retain('01-full-'+index,{source,serialized,direct,fromMeta});checkCst(direct.ir.concreteSyntaxMeta,source);assert.deepEqual(fromMeta,direct);assert.equal(direct.ir.sourceSha256,hash(source));assert.equal(direct.ir.items.map(row=>row.source).join(''),source);}
});

test('standalone CST passes checked semantic meta and executes independent JS and strict TS scalar edges',{timeout:60000},async()=>{
 const source='// café 🦀\r\npub fn choose(flag:bool)->u8{if flag{7}else{9}}\r\npub fn next(value:u8)->u8{value+1}';
 const result=translateSourceConcreteSyntaxMeta(serialize(source),'src/lib.rs');retain('02-real-standalone-targets',{source,result});checkCst(result.ir.concreteSyntaxMeta,source);assert.equal(result.ir.counts.executableFunctions,2);assert.equal(result.ir.counts.carried,0);
 for(const row of result.ir.items.filter(row=>row.status==='executable'))assert.ok(row.semantic.checkedIR.body.type);
 const observations=[];await verifyTypedTargets(result,api=>{const values=[api.choose(true),api.choose(false),api.next(0n),api.next(254n)];observations.push(values);assert.deepEqual(values,[7n,9n,1n,255n]);assert.throws(()=>api.next(255n),RangeError);assert.throws(()=>api.choose('true'),TypeError);},{childTimeoutMs:20000});retain('02-independent-results',{observations});assert.equal(observations.length,2);
});

test('serialized CST substitutions change actual checked JS and TS through fixed ordered phases',{timeout:60000},async()=>{
 const source='pub fn choose(flag:bool)->u8{if flag{7}else{9}}',original=createConcreteSyntaxMeta(source,{language:'Rust'}),start=source.indexOf('9');
 const edited=applyConcreteSyntaxSubstitutions(original,{languageRules:[{id:'literal-nine-to-eleven',edits:[{span:[start,start+1],expected:'9',replacement:'11'}]}],repositoryRules:[]});
 const serialized=serializeConcreteSyntaxMeta(edited.value),result=translateSourceConcreteSyntaxMeta(serialized),expected=source.slice(0,start)+'11'+source.slice(start+1);retain('03-edited-real-targets',{source,original,edited,serialized,result,expected});
 assert.deepEqual(edited.trace.map(row=>row.phase),['language','repository']);checkCst(original,source);checkCst(result.ir.concreteSyntaxMeta,expected);assert.equal(result.ir.sourceSha256,hash(expected));assert.notEqual(hash(expected),hash(source));
 await verifyTypedTargets(result,api=>{assert.equal(api.choose(true),7n);assert.equal(api.choose(false),11n);},{childTimeoutMs:20000});
});

test('complete physical project sources retain one CST with genuine inline views and checked meta before both targets',{timeout:60000},async()=>{
 const files={'src/lib.rs':'// root 🦀\r\npub mod math;mod local{pub fn value()->u8{2}}pub fn run(value:u8)->u8{math::add(value)+local::value()}','src/math.rs':'/* A /* B */ C */\npub fn add(value:u8)->u8{value+1}'};const reads=[];
 const result=translateProject({entry:'src/lib.rs',paths:Object.keys(files),readSource:path=>{reads.push(path);return files[path];}});retain('04-whole-project',{files,reads,result});
 assert.deepEqual(reads,['src/lib.rs','src/math.rs']);assert.deepEqual(result.meta.concreteSyntaxMeta.map(row=>row.source),reads);for(const row of result.meta.concreteSyntaxMeta)checkCst(row.document,files[row.source]);assert.equal(result.sourceScopes.length,3);assert.ok(result.sourceScopes.some(row=>row.module.join('.')==='local'));
 for(const row of result.meta.sources)assert.equal(row.sha256,hash(files[row.source]));for(const key of ['checkedSemanticProgram','targetSemanticProgram']){const text=JSON.stringify(result.meta[key]);assert.equal(serializeProgram(parseProgram(text)),text);}
 assert.deepEqual(result.meta.refused,[]);await verifyTypedTargets(result,api=>{assert.equal(api.run(3n),6n);assert.throws(()=>api.run(255n),RangeError);},{childTimeoutMs:20000});
 const aliases={'src/lib.rs':'#[path="shared.rs"]pub mod a;#[path="shared.rs"]pub mod b;pub fn both()->u8{a::value()+b::value()}','src/shared.rs':'pub fn value()->u8{3}'},aliasReads=[];
 const aliasOptions=events=>({entry:'src/lib.rs',paths:Object.keys(aliases),readSource:path=>{events.push({path,source:aliases[path]});return aliases[path];}});
 const aliased=resolveModuleGraph(aliasOptions(aliasReads));
 // Reuse the complete existing old whole-project fixture and its established
 // pin from project-rule-pipeline.test.mjs; no extracted/handwritten baseline.
 const originalProject=readFileSync(new URL('../fixtures/project-before-rule-pipeline-000151.mjs.txt',import.meta.url),'utf8');
 assert.equal(hash(originalProject),'f9ea0ff4818f913f3384a7053c0eda24149420aedab6711f0dd08ca8f69561e0');
 const projectRelocations=[],resolvedProject=originalProject.replace(/(\bfrom\s*['"])(\.[^'"]+)(['"])/gu,(_,a,b,c)=>{const to=new URL(b,new URL('../project.mjs',import.meta.url)).href;projectRelocations.push({from:b,to});return a+to+c;});
 const reversedProject=resolvedProject.replace(/(\bfrom\s*['"])([^'"]+)(['"])/gu,(_,a,b,c)=>a+(projectRelocations.find(row=>row.to===b)?.from??b)+c);
 assert.equal(reversedProject,originalProject);
 const oldProject=await import('data:text/javascript;base64,'+Buffer.from(resolvedProject).toString('base64')),attempts=[];
 for(const [label,implementation]of [['project-before-rule-pipeline-000151',oldProject.translateProject],['current',translateProject]]){
  const events=[];let returned,error;
  try{returned=implementation(aliasOptions(events));}catch(thrown){error={name:thrown.name,message:thrown.message,stack:thrown.stack,isTypeError:thrown instanceof TypeError};}
  attempts.push({label,events,returned,error});
 }
 retain('04-complete-repeated-physical-reads',{aliases,aliasReads,aliased,originalProject,resolvedProject,reversedProject,projectRelocations,attempts});
 assert.deepEqual(aliasReads.map(row=>row.path),['src/lib.rs','src/shared.rs','src/shared.rs']);assert.deepEqual(aliased.concreteSyntaxMeta.map(row=>row.source),aliasReads.map(row=>row.path));
 for(let at=0;at<aliasReads.length;at++)checkCst(aliased.concreteSyntaxMeta[at].document,aliasReads[at].source);
 assert.deepEqual(aliased.diagnostics,[]);assert.deepEqual(aliased.modules.map(row=>({file:row.file,path:row.path,source:row.source})),[{file:'src/lib.rs',path:[],source:aliases['src/lib.rs']},{file:'src/shared.rs',path:['a'],source:aliases['src/shared.rs']},{file:'src/shared.rs',path:['b'],source:aliases['src/shared.rs']}]);
 assert.equal(aliased.concreteSyntaxMeta.filter(row=>row.source==='src/shared.rs').length,2);assert.notEqual(aliased.concreteSyntaxMeta[1].document,aliased.concreteSyntaxMeta[2].document);
 for(const row of attempts){assert.equal(row.returned,undefined);assert.equal(row.error?.isTypeError,true);assert.equal(row.error.name,'TypeError');assert.equal(row.error.message,'Same-file macro view origins disagree with actual module paths/source');assert.deepEqual(row.events,aliasReads);}
 assert.equal(attempts[0].error.message,attempts[1].error.message);
});

test('CST fidelity never supplies macro shadow borrowed or transitive dependency authority',{timeout:60000},async()=>{
 const source='pub fn good(value:u8)->u8{value+1}pub fn blocked()->bool{unknown!()}pub fn caller()->bool{blocked()}';const result=translateProject({entry:'src/lib.rs',paths:['src/lib.rs'],readSource:()=>source}),standalone=translateSourceConcreteSyntaxMeta(serialize(source));retain('05-refused-semantics',{source,result,standalone});
 checkCst(result.meta.concreteSyntaxMeta[0].document,source);assert.deepEqual(result.meta.executable.map(row=>row.name),['good']);assert.ok(result.meta.refused.some(row=>row.name==='blocked'));assert.ok(result.meta.refused.some(row=>row.name==='caller'));assert.equal(standalone.ir.items.some(row=>row.name==='blocked'&&row.status==='executable'),false);
 await verifyTypedTargets(result,api=>{assert.equal(api.good(2n),3n);assert.equal(Object.hasOwn(api,'blocked'),false);assert.equal(Object.hasOwn(api,'caller'),false);},{childTimeoutMs:20000});
 const borrowed='pub fn blocked(value:&mut u8)->u8{*value}';const refusal=translateProject({entry:'src/lib.rs',paths:['src/lib.rs'],readSource:()=>borrowed});retain('05-borrow-refusal',{borrowed,refusal});assert.equal(refusal.meta.executable.some(row=>row.name==='blocked'),false);
});

test('whole opaque or malformed lexical sources preserve bytes without bypassing original failures',{timeout:60000},()=>{
 for(const [index,source]of ['/* unterminated nested /* comment','pub fn broken(){r###"unterminated','pub fn broken(){ unknown!({] }'].entries()){
  const serialized=serialize(source),document=parseConcreteSyntaxMeta(serialized),direct=outcome(()=>translateSource(source)),fromMeta=outcome(()=>translateSourceConcreteSyntaxMeta(serialized));retain('06-opaque-'+index,{source,serialized,document,direct,fromMeta});checkCst(document,source);assert.notEqual(document.status,'lexical');assert.deepEqual(fromMeta,direct);if(direct.value)assert.equal(direct.value.ir.counts.executableFunctions,0);
 }
});

test('noncanonical foreign and forged CST documents refuse before semantic checks and genuine input stays valid',{timeout:60000},()=>{
 const source='pub fn value()->u8{3}',canonical=serialize(source),document=JSON.parse(canonical),inputs=[canonical+'\n',JSON.stringify({...document,extra:true}),JSON.stringify({...document,authority:{type:true,owner:true,executable:true}}),canonical.replace('"schema":','"schema":"duplicate","schema":'),serializeConcreteSyntaxMeta(createConcreteSyntaxMeta('export const value=3;',{language:'JavaScript'}))];const observations=inputs.map(input=>({input,outcome:outcome(()=>translateSourceConcreteSyntaxMeta(input))}));retain('07-invalid-documents',{source,canonical,observations});for(const row of observations)assert.ok(row.outcome.error);
 const result=translateSourceConcreteSyntaxMeta(canonical);checkCst(result.ir.concreteSyntaxMeta,source);assert.equal(result.ir.counts.executableFunctions,1);
});

test('complete pre-CST consumer output and original callback reads remain exact apart from the independently checked persistent CST',{timeout:60000},()=>{
 for(const [index,source]of ['pub fn choose(flag:bool)->u8{if flag{7}else{9}}','pub fn unsupported()->bool{unknown!()}','/* full comment */pub const SMALL:u8=3;pub fn value()->u8{SMALL}'].entries()){
  const before=prior.translateSource(source,'src/lib.rs'),after=translateSource(source,'src/lib.rs');retain('08-full-old-current-'+index,{source,beforeSource,relocatedBefore,reverseBefore,relocations,before,after});checkCst(after.ir.concreteSyntaxMeta,source);assert.deepEqual(plain(after),before);
 }
 const descriptor=Object.getOwnPropertyDescriptor,define=Object.defineProperty,parseDescriptor=descriptor(JSON,'parse'),sourceWithOptions='pub fn choose(flag:bool)->u8{if flag{7}else{9}}',optionRows=[];
 for(const implementation of [prior.translateSource,translateSource]){
  const events=[];let calls=0,result,error;
  const options={get projectDeclarations(){events.push('projectDeclarations');define(JSON,'parse',parseDescriptor);return undefined;},get projectSourceScopes(){events.push('projectSourceScopes');return undefined;},get jsonParserProfile(){events.push('jsonParserProfile');return undefined;},get cargoManifest(){events.push('cargoManifest');return undefined;}};
  try{define(JSON,'parse',{...parseDescriptor,value:function changedParse(){calls++;throw Error('option getter must restore parse before source stage');}});try{result=implementation(sourceWithOptions,'src/lib.rs',options);}catch(thrown){error={name:thrown.name,message:thrown.message};}}
  finally{define(JSON,'parse',parseDescriptor);}
  optionRows.push({events,calls,result,error});
 }
 retain('08-complete-original-option-order',{sourceWithOptions,optionRows});for(const row of optionRows){assert.equal(row.error,undefined);assert.equal(row.calls,0);assert.deepEqual(row.events,['projectDeclarations','projectSourceScopes','jsonParserProfile','cargoManifest']);}
 checkCst(optionRows[1].result.ir.concreteSyntaxMeta,sourceWithOptions);assert.deepEqual(plain(optionRows[1].result),optionRows[0].result);assert.deepEqual(optionRows[1].events,optionRows[0].events);
 const source='mod inline{pub fn value()->u8{1}}pub fn run()->u8{inline::value()}',reads=[],graph=resolveModuleGraph({entry:'src/lib.rs',paths:['src/lib.rs'],readSource:path=>{reads.push(path);return source;},compilationProfile:PRODUCTION_PROFILE});retain('08-source-read-callbacks',{source,reads,graph});assert.deepEqual(reads,['src/lib.rs']);assert.equal(graph.concreteSyntaxMeta.length,1);assert.equal(graph.modules.length,2);checkCst(graph.concreteSyntaxMeta[0].document,source);
});
